# shellcheck shell=bash
# Completions for DevBootstrapper commands. Tool completions are generated by devup into
# tools/completions/ and loaded lazily by bash-completion (BASH_COMPLETION_USER_DIR).

if ! declare -F _comp_initialize >/dev/null 2>&1 && ! declare -F _init_completion >/dev/null 2>&1; then
  # shellcheck disable=SC1091
  [ -r /usr/share/bash-completion/bash_completion ] && . /usr/share/bash-completion/bash_completion
fi

__devboot_complete_gitid() {
  local cur=${COMP_WORDS[COMP_CWORD]} prev=${COMP_WORDS[COMP_CWORD-1]} words=''
  if [ "$COMP_CWORD" -eq 1 ]; then
    words='list add-account add-context link unlink remove-account remove-context default use as setup sync doctor'
  else
    case ${COMP_WORDS[1]} in
      default | use | add-context | remove-context | link | unlink)
        words="$(git config -f "$DEV_HOME/.local/git/identities.gitconfig" --name-only --get-regexp '^context\..*\.email$' 2>/dev/null | sed -E 's/^context\.(.*)\.email$/\1/')"
        [ "${COMP_WORDS[1]}" = use ] && words="$words --clear"
        if [ "$COMP_CWORD" -eq 3 ]; then
          words="$(git config -f "$DEV_HOME/.local/git/identities.gitconfig" --name-only --get-regexp '^account\..*\.host$' 2>/dev/null | sed -E 's/^account\.(.*)\.host$/\1/')"
        fi
        ;;
      as | remove-account)
        words="$(git config -f "$DEV_HOME/.local/git/identities.gitconfig" --name-only --get-regexp '^account\..*\.host$' 2>/dev/null | sed -E 's/^account\.(.*)\.host$/\1/')"
        ;;
    esac
  fi
  : "$prev"
  mapfile -t COMPREPLY < <(compgen -W "$words" -- "$cur")
}
complete -F __devboot_complete_gitid gitid

__devboot_complete_use_version() {
  local cur=${COMP_WORDS[COMP_CWORD]} words
  if [ "$COMP_CWORD" -eq 1 ]; then
    words=$(sed -n 's/^\([A-Za-z0-9_-]*\) = \[.*/\1/p' "$DEV_HOME/config/mise/config.toml")
  else
    words="--reset $(use-version --list-values "${COMP_WORDS[1]}" 2>/dev/null)"
  fi
  mapfile -t COMPREPLY < <(compgen -W "$words" -- "$cur")
}
complete -F __devboot_complete_use_version use-version

__devboot_complete_tool_use() {
  local tool=$1 cur=${COMP_WORDS[COMP_CWORD]}
  mapfile -t COMPREPLY < <(compgen -W "--reset $(use-version --list-values "$tool" 2>/dev/null)" -- "$cur")
}
__devboot_complete_mvnuse() { __devboot_complete_tool_use maven; }
__devboot_complete_jdkuse() { __devboot_complete_tool_use java; }
complete -F __devboot_complete_mvnuse mvnuse
complete -F __devboot_complete_jdkuse jdkuse

complete -W "help cheat docs ids up doctor startup-time version" dev
complete -W "--first-run --daily --skip --only --unlink --help" devup
